pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, uint unlockTime, uint putAmount, uint collectAmount) public {
        vm.assume(sender != address(0) && sender != address(c));
        vm.assume(putAmount >= 0.1 ether && putAmount <= 100 ether);
        vm.assume(collectAmount >= 0.1 ether && collectAmount <= 100 ether);
        vm.assume(putAmount >= collectAmount);

        // Record initial balance of sender
        uint initialSenderBalance = address(sender).balance;

        // First call Put to deposit
        vm.deal(sender, putAmount);
        vm.prank(sender);
        c.Put{value: putAmount}(unlockTime);

        // Then call Collect
        vm.prank(sender);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The general rule: after Collect, the sender's balance should never exceed the original balance + putAmount (minus any gas costs)
        // In a correct contract, the sender cannot get more than they deposited
        uint finalSenderBalance = address(sender).balance;
        // Allow up to 0.01 ether for gas costs
        assertTrue(finalSenderBalance <= initialSenderBalance + putAmount + 0.01 ether);
    }
}

