pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint unlockTime, uint putAmount, uint collectAmount) public {
        // The test will: 1) make a Put call (via fallback or directly) and then a Collect call.
        // The general rule: after the Collect call, the caller's balance in Acc is never negative.
        // Since the reference contract correctly uses addition (acc.balance += msg.value) in Put,
        // whereas the mutant uses subtraction (acc.balance -= msg.value), the mutant can make the balance negative.

        // Ensure collectAmount does not exceed putAmount to avoid revert in Collect for valid state.
        vm.assume(collectAmount <= putAmount);
        vm.assume(putAmount > 0); // avoid zero put

        // Set up: give this contract some ether to send
        vm.deal(address(this), putAmount);

        // Step 1: Call Put with putAmount via fallback (sets unlockTime = 0, but any unlockTime is fine)
        (bool successPut, ) = address(c).call{value: putAmount}("");
        assertTrue(successPut, "Put via fallback should succeed");

        // Step 2: Call Collect with collectAmount
        (bool successCollect, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        // Collect may revert if conditions not met, but we only care about state when it succeeds
        if (successCollect) {
            // The rule: after a successful Collect, the caller's balance in Acc is non-negative.
            // The public getter Acc(address) returns (uint256 unlockTime, uint256 balance).
            (, uint256 balanceAfter) = c.Acc(address(this));
            assertTrue(balanceAfter >= 0, "Balance should never be negative");
        }
    }
}

